import { createRequire } from 'node:module';
import { performance } from 'node:perf_hooks';
const require = createRequire(process.cwd() + '/package.json');
const rough = require('roughjs');
const version = require('roughjs/package.json').version;
const g = rough.generator();
const recipe = { roughness: 2.2, maxRandomnessOffset: 2, bowing: 1.2, preserveVertices: true, disableMultiStroke: false, fillStyle: 'solid', fillShapeRoughnessGain: 0, stroke: '#222', strokeWidth: 1.25 };
const rounded = 'M8 0H112A8 8 0 0 1 120 8V56A8 8 0 0 1 112 64H8A8 8 0 0 1 0 56V8A8 8 0 0 1 8 0Z';
let complex = 'M0 0';
for (let j = 0; j < 128; j++) complex += 'C' + [j*4+1, Math.sin(j)*30, j*4+3, Math.cos(j)*30, j*4+4, Math.sin(j+1)*30].join(' ');
const scenarios = [
  ['line / current', 1000, i => g.line(0,0,120,64,{...recipe,seed:i+1})],
  ['rect solid / current', 1000, i => g.rectangle(0,0,120,64,{...recipe,fill:'#ddd',seed:i+1})],
  ['rounded path solid / current', 1000, i => g.path(rounded,{...recipe,fill:'#ddd',seed:i+1})],
  ['rounded path stroke only / current', 1000, i => g.path(rounded,{...recipe,seed:i+1})],
  ['rounded path stroke only / single', 1000, i => g.path(rounded,{...recipe,disableMultiStroke:true,seed:i+1})],
  ['128-cubic path stroke only', 100, i => g.path(complex,{...recipe,seed:i+1})],
  ['rect hachure gap 4', 100, i => g.rectangle(0,0,120,64,{...recipe,fill:'#ddd',fillStyle:'hachure',hachureGap:4,seed:i+1})],
  ['rect hachure gap 1', 100, i => g.rectangle(0,0,120,64,{...recipe,fill:'#ddd',fillStyle:'hachure',hachureGap:1,seed:i+1})]
];
const pct = (a,p) => [...a].sort((x,y)=>x-y)[Math.ceil(a.length*p)-1];
let sink = 0;
const results = [];
for (const [name,n,fn] of scenarios) {
  for(let warm=0;warm<5;warm++) for(let i=0;i<n;i++) sink += fn(i).sets.length;
  const generate=[], serialize=[];
  let count=0, layers=0, bytes=0;
  for(let sample=0;sample<21;sample++) {
    const drawables = new Array(n);
    let t=performance.now();
    for(let i=0;i<n;i++) drawables[i]=fn(i);
    generate.push(performance.now()-t);
    t=performance.now();
    let b=0;
    for(const d of drawables) for(const p of g.toPaths(d)) b += p.d.length;
    serialize.push(performance.now()-t); sink+=b;
    if(sample===20) {bytes=b;for(const d of drawables){layers+=d.sets.length;for(const s of d.sets) count+=s.ops.length;}}
  }
  results.push({name,shapes:n,generateMedianMs:+pct(generate,.5).toFixed(3),generateP95Ms:+pct(generate,.95).toFixed(3),serializeMedianMs:+pct(serialize,.5).toFixed(3),operationsPerShape:count/n,layersPerShape:layers/n,pathCharsPerShape:Math.round(bytes/n)});
}
console.log(JSON.stringify({runtime:process.version,version,platform:process.platform,arch:process.arch,samples:21,warmupBatches:5,measurement:'Generator and d serialization only; no DOM, layout, paint, cache or worker',results,sink},null,2));
